    kind=${pair%%:*}
    value=${pair#*:}
    [ -n "$value" ] || fail "$kind is required"
    python3 "$REPORT_SH" stall-recovery validate-token --profile generic --artifact-prefix design-failure --implement-tmpdir "$DESIGN_TMPDIR" --token-kind "$kind" --value "$value" >/dev/null
